const articles=[{id:'electric-tractor-selection',category:'model-guide',label:'MODEL GUIDE',date:'September 7, 2026',time:'8 min read',title:'How to Select a Dongfeng Electric Tractor for Port and Regional Haulage',excerpt:'Compare GCW, battery capacity, charging interface and route requirements across the TE46, TE8 and TE9 platforms.',image:'assets/tractor.jpg'},{id:'electric-dump-truck-guide',category:'application',label:'APPLICATION',date:'September 7, 2026',time:'7 min read',title:'Electric Dump Trucks for Mining and Construction: What Buyers Should Check',excerpt:'A practical checklist covering grade, payload, frame strength, battery, charging and right-hand-drive options.',image:'assets/dumper.jpg'},{id:'ev-truck-range-tco',category:'tco',label:'TCO & CHARGING',date:'September 7, 2026',time:'6 min read',title:'How Duty Cycle Affects Electric Truck Range and Total Cost',excerpt:'Why daily mileage, payload, average speed, road grade and charging windows matter more than one headline range figure.',image:'assets/cargo.jpg'}];let category='all';const grid=document.querySelector('#articleGrid'),search=document.querySelector('#articleSearch');function render(){const q=search.value.toLowerCase().trim();const results=articles.filter(a=>(category==='all'||a.category===category)&&(!q||(a.title+' '+a.excerpt).toLowerCase().includes(q)));grid.innerHTML=results.map(a=>`<article><a class="article-image" href="article.html?id=${a.id}"><img src="${a.image}" alt="${a.title}"></a><div><span>${a.label} · ${a.time}</span><h2><a href="article.html?id=${a.id}">${a.title}</a></h2><p>${a.excerpt}</p><small>${a.date}</small><a class="read" href="article.html?id=${a.id}">Read article →</a></div></article>`).join('');document.querySelector('#emptyState').hidden=results.length>0}document.querySelectorAll('.filters button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');category=b.dataset.category;render()}));search.addEventListener('input',render);document.querySelector('.menu').addEventListener('click',e=>{document.querySelector('.topbar').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',document.querySelector('.topbar').classList.contains('open'))});render();
